    private static func icon(
        _ id: String,
        _ category: LimeghostIconCategory,
        _ markup: String
    ) -> LimeghostIcon {
        LimeghostIcon(
            id: id,
            category: category,
            markup: markup,
            style: .emojiOne,
            box: VectorBox(x: 0, y: 0, width: 64, height: 64)
        )
    }
